```sql
SELECT (
    (SELECT SUM(total_amount) FROM orders WHERE strftime('%Y-%m', ordered_at) = '2026-03')
    -
    (SELECT SUM(refund_amount) FROM refunds WHERE order_id IN (
        SELECT order_id FROM orders WHERE strftime('%Y-%m', ordered_at) = '2026-03'
    ))
) AS net_sales;
```

